package com.lexorion.payroll.domain;import jakarta.persistence.*;import java.time.Instant;import lombok.Getter;import org.springframework.data.annotation.*;import org.springframework.data.jpa.domain.support.AuditingEntityListener;@MappedSuperclass@EntityListeners(AuditingEntityListener.class)@Getter public abstract class Auditable{@CreatedDate@Column(nullable=false,updatable=false)private Instant createdAt;@LastModifiedDate@Column(nullable=false)private Instant updatedAt;}
